/**
 * Latin-core Open Runde faces embedded as base64 data: URIs, so emails render the
 * same brand font as the app (`apps/web/src/index.css`). Generated — do not edit
 * the `src:` lines by hand. To rebuild from the app faces (needs `uvx`), for
 * each of OpenRunde-Medium.woff2 and OpenRunde-Semibold.woff2:
 *
 *   uvx --from fonttools[woff] pyftsubset OpenRunde-<W>.woff2 --flavor=woff2 \
 *     --output-file=<w>.woff2 \
 *     --unicodes="U+0020-007E,U+00A0,U+2013-2014,U+2018-201D,U+2022,U+2026,\
 *     U+2192,U+20AC" --layout-features="kern,liga,calt"
 *
 * then base64 each output into the `src:` line below (Medium -> 400-550,
 * Semibold -> 551-800).
 *
 * The charset is the ASCII core plus the characters the emails actually render:
 * nbsp, en/em dashes, curly quotes, bullet, ellipsis, the right arrow and the
 * euro sign. Any other character falls through `EMAIL_FONT_STACK` to the system
 * stack — the same behaviour as before this file existed.
 *
 * Client support: Gmail and Outlook desktop strip `@font-face` and use the
 * stack fallbacks; Apple Mail, iOS Mail, Outlook.com and Thunderbird load the
 * data: faces. The payload is ~36 KB total, which keeps long briefings under
 * Gmail's ~102 KB message-clip threshold.
 */

/** The two @font-face rules for the email `<style>` block. */
export const EMAIL_FONT_FACE_CSS = `
@font-face {
  font-family: "Open Runde";
  font-style: normal;
  font-weight: 400 550;
  font-display: swap;
  src: url(data:font/woff2;base64,);
}
@font-face {
  font-family: "Open Runde";
  font-style: normal;
  font-weight: 551 800;
  font-display: swap;
  src: url(data:font/woff2;base64,);
}
`;

/**
 * The email font stack. `Open Runde` wins where the face above loaded; the tail
 * mirrors the app's `--font-sans` fallbacks (`apps/web/src/index.css`), with
 * the mail-client extras kept.
 */
export const EMAIL_FONT_STACK =
  '"Open Runde", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
